(function() {
    'use strict';

    class BusinessModelAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `7 Steps to a Business Model`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` },
                { id: 5, titleKey: `briefing_title_r5`, textKey: `briefing_text_r5`, panelId: `round5Panel`, nameKey: `round_name_r5`, clockKey: `clock_r5` }
            ];

            // Numbers reference card (EUR).
            this.START_RUNWAY = 1800000;      // EUR 1.8M net cash / ~14 months
            this.BUDGET_CAP = 700;            // EUR 700k pivot investment, in thousands
            this.START_COHERENCE = 20;
            this.START_CONFIDENCE = 15;
            this.APPROVE_THRESHOLD = 70;      // investor confidence to approve a pivot
            this.CONVERSION_LOW = 35;         // realistic conversion band 35-45%
            this.CONVERSION_HIGH = 45;
            this.PLANT_MONTHLY = 95000;       // EUR 95k/month stranded fixed cost
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    coherence: this.START_COHERENCE,
                    confidence: this.START_CONFIDENCE,
                    runway: this.START_RUNWAY,
                    budgetUsed: 0,
                    insolvent: false,
                    boardBlocked: false,
                    coherenceHistory: [this.START_COHERENCE],
                    confidenceHistory: [this.START_CONFIDENCE],
                    runwayHistory: [Math.round(this.START_RUNWAY / 10000)],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    diag: `structural`,
                    asset: `content`,
                    honesty: 60,
                    vp: `digitalpresence`,
                    focus: `sharp`,
                    conversion: 40,
                    revenue: `subscription`,
                    cashmodel: `slow`,
                    invest: 450,
                    plant: `reconfigure`,
                    team: `retrain`,
                    designers: `retain`,
                    coherenceEffort: 60,
                    pitch: `coherent`,
                    risk: `conversion`,
                    margin: 14,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const diag = document.getElementById(`diagInput`);
                const asset = document.getElementById(`assetInput`);
                const hon = document.getElementById(`honestyInput`);
                if (diag) decisions.diag = diag.value;
                if (asset) decisions.asset = asset.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const vp = document.getElementById(`vpInput`);
                const focus = document.getElementById(`focusInput`);
                const conv = document.getElementById(`conversionInput`);
                if (vp) decisions.vp = vp.value;
                if (focus) decisions.focus = focus.value;
                if (conv) decisions.conversion = parseInt(conv.value, 10);
                if (!Number.isFinite(decisions.conversion) || decisions.conversion < 0 || decisions.conversion > 100) {
                    warn(`warn_conversion_range`); return false;
                }
            } else if (round === 3) {
                const rev = document.getElementById(`revenueInput`);
                const cm = document.getElementById(`cashmodelInput`);
                const inv = document.getElementById(`investInput`);
                if (rev) decisions.revenue = rev.value;
                if (cm) decisions.cashmodel = cm.value;
                if (inv) decisions.invest = parseFloat(inv.value);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0) {
                    warn(`warn_invest_negative`); return false;
                }
                if (decisions.invest > this.BUDGET_CAP) {
                    warn(`warn_invest_cap`); return false;
                }
            } else if (round === 4) {
                const plant = document.getElementById(`plantInput`);
                const team = document.getElementById(`teamInput`);
                const des = document.getElementById(`designersInput`);
                const coh = document.getElementById(`coherenceInput`);
                if (plant) decisions.plant = plant.value;
                if (team) decisions.team = team.value;
                if (des) decisions.designers = des.value;
                if (coh) decisions.coherenceEffort = parseInt(coh.value, 10);
                if (!Number.isFinite(decisions.coherenceEffort) || decisions.coherenceEffort < 0 || decisions.coherenceEffort > 100) {
                    warn(`warn_coherence_range`); return false;
                }
            } else if (round === 5) {
                const pitch = document.getElementById(`pitchInput`);
                const risk = document.getElementById(`riskInput`);
                const margin = document.getElementById(`marginInput`);
                const conv = document.getElementById(`convictionInput`);
                if (pitch) decisions.pitch = pitch.value;
                if (risk) decisions.risk = risk.value;
                if (margin) decisions.margin = parseFloat(margin.value);
                if (conv) decisions.conviction = parseInt(conv.value, 10);
                if (!Number.isFinite(decisions.margin) || decisions.margin < 0 || decisions.margin > 40) {
                    warn(`warn_margin_range`); return false;
                }
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // coherence = the fit between value <-> revenue <-> operations (the central concept).
            // confidence = the lead investor's / board's belief in the pivot.
            // cashSpend = EUR drawn from the runway this step (investment + any stranded cost).
            let coherenceDelta = 0, confidenceDelta = 0;
            let cashSpend = 0, budgetSpend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Common Error 1: redesigning without diagnosing. Diagnose the structural cause first.
                switch (d.diag) {
                    case `structural`: coherenceDelta += 9; confidenceDelta += 7; coachKey = `coach_r1_structural`; break;
                    case `margin`: coherenceDelta += 1; confidenceDelta -= 5; coachKey = `coach_r1_margin`; break;
                    case `sales`: coherenceDelta -= 5; confidenceDelta -= 7; coachKey = `coach_r1_sales`; break;
                    case `skip`: coherenceDelta -= 12; confidenceDelta -= 12; coachKey = `coach_r1_skip`; break;
                }

                // The crown jewel is the content + relationships, not the plant.
                switch (d.asset) {
                    case `content`: coherenceDelta += 7; confidenceDelta += 4; break;
                    case `plant`: coherenceDelta -= 9; confidenceDelta -= 5; coachKey = `coach_r1_plant`; break;
                    case `brand`: coherenceDelta += 1; break;
                }

                // Honesty: willingness to redesign rather than cost-cut the dying model.
                if (d.honesty >= 60) { confidenceDelta += 4; }
                else if (d.honesty <= 25) { confidenceDelta -= 9; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.diag === `structural` && d.asset === `content`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Common Error 2: inside-out value proposition. Anchor in the SME's real job.
                switch (d.vp) {
                    case `digitalpresence`: coherenceDelta += 10; confidenceDelta += 7; coachKey = `coach_r2_job`; break;
                    case `designtools`: coherenceDelta -= 9; confidenceDelta -= 7; coachKey = `coach_r2_insideout`; break;
                    case `premiumprint`: coherenceDelta -= 5; confidenceDelta -= 5; coachKey = `coach_r2_print`; break;
                    case `everything`: coherenceDelta -= 7; confidenceDelta -= 7; coachKey = `coach_r2_everything`; break;
                }

                // Strategy is as much about what you will NOT do.
                if (d.focus === `sharp`) { coherenceDelta += 5; confidenceDelta += 3; }
                else { coherenceDelta -= 6; coachKey = (d.vp === `digitalpresence`) ? `coach_r2_unfocused` : coachKey; }

                // Common Error 5: over-assuming conversion of the 600-client base.
                if (d.conversion >= this.CONVERSION_LOW && d.conversion <= this.CONVERSION_HIGH) {
                    confidenceDelta += 7; coherenceDelta += 3;
                } else if (d.conversion > 60) {
                    confidenceDelta -= 13; coherenceDelta -= 5; coachKey = `coach_r2_overconvert`;
                } else if (d.conversion < this.CONVERSION_LOW) {
                    confidenceDelta -= 2;
                } else {
                    confidenceDelta += 2;
                }

                summaryKey = (d.vp === `digitalpresence` && d.focus === `sharp` && d.conversion <= this.CONVERSION_HIGH) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Choose the monetization logic deliberately and model its cash-flow shape.
                let revCoh = 0, revConf = 0;
                switch (d.revenue) {
                    case `subscription`: revCoh = 9; revConf = 7; coachKey = `coach_r3_subscription`; break;
                    case `platform`: revCoh = 5; revConf = 4; coachKey = `coach_r3_platform`; break;
                    case `project`: revCoh = -7; revConf = -7; coachKey = `coach_r3_project`; break;
                    case `freemium`: revCoh = 2; revConf = 1; coachKey = `coach_r3_freemium`; break;
                }
                coherenceDelta += revCoh; confidenceDelta += revConf;

                // Common Error 3: mis-modelling subscription cash flow as if it were project revenue.
                const recurring = (d.revenue === `subscription` || d.revenue === `freemium`);
                if (d.cashmodel === `slow`) {
                    confidenceDelta += 5; coherenceDelta += 3;
                } else { // frontloaded
                    if (recurring) { confidenceDelta -= 15; coherenceDelta -= 5; coachKey = `coach_r3_frontload`; }
                    else { confidenceDelta -= 2; }
                }

                // Pivot investment: drawn from runway, capped at EUR 700k. Too little starves the build.
                budgetSpend += d.invest;
                cashSpend += d.invest * 1000;
                if (d.invest >= 400 && d.invest <= 650) { coherenceDelta += 5; confidenceDelta += 3; }
                else if (d.invest < 250) { coherenceDelta -= 9; confidenceDelta -= 7; coachKey = `coach_r3_underinvest`; }
                else if (d.invest > 650) { confidenceDelta -= 2; }

                // The subscription cash trough: recurring revenue mis-modelled as front-loaded means the
                // company spends now against year-one revenue that never lands on schedule. The deeper the
                // build you front-loaded, the deeper the trough — compounded with over-investment and a
                // retained plant, this is how a model dies solvent-on-paper before break-even.
                if (recurring && d.cashmodel === `frontloaded`) { cashSpend += d.invest * 1000 + 350000; }

                summaryKey = (d.cashmodel === `slow` && (d.revenue === `subscription` || d.revenue === `platform`) && d.invest >= 400) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Common Error 4: incoherent operating model — bolt digital onto the print cost base.
                switch (d.plant) {
                    case `reconfigure`: coherenceDelta += 7; confidenceDelta += 5; coachKey = `coach_r4_reconfigure`; break;
                    case `keep`: coherenceDelta -= 13; confidenceDelta -= 9; coachKey = `coach_r4_keep`; cashSpend += this.PLANT_MONTHLY * 2; break;
                    case `closeall`: coherenceDelta -= 5; confidenceDelta -= 7; coachKey = `coach_r4_closeall`; cashSpend += 180000; break;
                }

                switch (d.team) {
                    case `retrain`: coherenceDelta += 3; confidenceDelta += 3; break;
                    case `asis`: coherenceDelta -= 9; confidenceDelta -= 5; coachKey = `coach_r4_teamasis`; break;
                    case `gutall`: coherenceDelta -= 5; confidenceDelta -= 7; coachKey = `coach_r4_gutall`; break;
                }

                // The two senior designers are the engine of any digital build.
                switch (d.designers) {
                    case `retain`: coherenceDelta += 2; confidenceDelta += 5; break;
                    case `hope`: coherenceDelta -= 9; confidenceDelta -= 11; coachKey = `coach_r4_designershope`; break;
                    case `release`: coherenceDelta -= 13; confidenceDelta -= 13; coachKey = `coach_r4_designersrelease`; break;
                }

                // Effort spent resolving the contradictions between the three pillars.
                if (d.coherenceEffort >= 60) { coherenceDelta += 2; }
                else if (d.coherenceEffort <= 25) { coherenceDelta -= 9; coachKey = `coach_r4_loweffort`; }

                summaryKey = (d.plant === `reconfigure` && d.team === `retrain` && d.designers === `retain`) ? `sum_r4_good` : `sum_r4_weak`;
            } else if (round === 5) {
                // Pitch: a strong model is coherent, not a collection of clever-but-disconnected ideas.
                switch (d.pitch) {
                    case `coherent`: coherenceDelta += 8; confidenceDelta += 10; coachKey = `coach_r5_coherent`; break;
                    case `bolton`: coherenceDelta -= 11; confidenceDelta -= 15; coachKey = `coach_r5_bolton`; break;
                    case `vision`: coherenceDelta -= 5; confidenceDelta -= 7; coachKey = `coach_r5_vision`; break;
                }

                // Naming the real risk honestly (the conversion of the 600 clients) is credible.
                switch (d.risk) {
                    case `conversion`: confidenceDelta += 7; coherenceDelta += 3; coachKey = (d.pitch === `coherent`) ? `coach_r5_riskhonest` : coachKey; break;
                    case `none`: confidenceDelta -= 11; coachKey = `coach_r5_risknone`; break;
                    case `competitor`: confidenceDelta += 1; break;
                }

                // A coherent pivot can credibly defend a low-teens recurring margin; over-claiming hurts.
                if (d.margin >= 10 && d.margin <= 18) { confidenceDelta += 4; coherenceDelta += 1; }
                else if (d.margin > 25) { confidenceDelta -= 9; coachKey = `coach_r5_overmargin`; }
                else if (d.margin < 6) { confidenceDelta -= 2; }

                // Conviction nudges investor confidence.
                confidenceDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.pitch === `coherent` && d.risk === `conversion`) ? `sum_r5_good` : `sum_r5_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(ds.budgetUsed + budgetSpend));
            ds.runway = Math.max(0, Math.round(ds.runway - cashSpend));
            if (ds.runway <= 0) { ds.insolvent = true; }

            // Coherence and confidence move on their deltas, clamped 0-100.
            ds.coherence = Math.max(0, Math.min(100, ds.coherence + coherenceDelta));
            ds.confidence = Math.max(0, Math.min(100, ds.confidence + confidenceDelta));

            // Running out of cash craters investor confidence — you died solvent-on-paper.
            if (ds.insolvent) {
                ds.confidence = Math.max(0, Math.min(ds.confidence, 25));
                ds.coherence = Math.max(0, ds.coherence - 8);
            }

            // The board blocks a final model that is incoherent or has lost their confidence.
            if (round === this.ROUNDS.length) {
                if (ds.confidence < this.APPROVE_THRESHOLD || ds.coherence < 55 || ds.insolvent) ds.boardBlocked = true;
            }

            ds.coherenceHistory.push(Math.round(ds.coherence));
            ds.confidenceHistory.push(Math.round(ds.confidence));
            ds.runwayHistory.push(Math.round(ds.runway / 10000));

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                coherence: Math.round(ds.coherence),
                coherenceDelta: Math.round(coherenceDelta),
                confidence: Math.round(ds.confidence),
                confidenceDelta: Math.round(confidenceDelta),
                runway: Math.round(ds.runway),
                budgetUsed: ds.budgetUsed,
                insolvent: ds.insolvent,
                boardBlocked: ds.boardBlocked,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _money(eur) {
            // Locale-aware EUR formatter. EN: €1.80M / €450k. ES: 1,80 M€ / 450k €.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Number(eur) || 0;
            if (lang === `es`) {
                if (Math.abs(n) >= 1000000) return (n / 1000000).toFixed(2).replace(`.`, `,`) + ` M€`;
                return Math.round(n / 1000) + `k €`;
            }
            if (Math.abs(n) >= 1000000) return `€` + (n / 1000000).toFixed(2) + `M`;
            return `€` + Math.round(n / 1000) + `k`;
        }

        _budgetLabel(kEur) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const used = Math.round(Number(kEur) || 0);
            if (lang === `es`) return `${used}k € / 700k €`;
