        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.coherenceHistory.map((_, i) => (i === 0 ? `Start` : `S` + i));
            return {
                bizmodelChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.coherenceHistory },
                        { data: ds.confidenceHistory },
                        { data: ds.runwayHistory }
                    ]
