        // Shared composite (0-100). Written to domainState.performance.overallScore each period
        // for the reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            var coherence = Math.round(ds.coherence || 0);
            var confidence = Math.round(ds.confidence || 0);
            var runway = Math.round(ds.runway || 0);
            return Math.round(Math.min(100, coherence) * 0.4 + confidence * 0.4 + Math.min(100, Math.max(0, runway / 18000)) * 0.2);
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const coherence = Math.round(ds.coherence);
            const confidence = Math.round(ds.confidence);
            const runway = Math.round(ds.runway);

            const approved = confidence >= this.APPROVE_THRESHOLD && coherence >= 55 && !ds.insolvent;
            const strong = approved && coherence >= 70 && confidence >= 75;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_prepared`;
            if (strong && composite >= 74) performanceKey = `grade_reinvented`;
            else if (approved) performanceKey = `grade_approved`;
            else if (ds.insolvent) performanceKey = `grade_insolvent`;
            else if (coherence >= 55 && confidence < this.APPROVE_THRESHOLD) performanceKey = `grade_coherent`;
            else if (coherence < 45) performanceKey = `grade_incoherent`;
            const performance = T(performanceKey);

            const insights = [];
            if (strong) insights.push(window.mySimulation.t(`insight_reinvented`));
            else if (approved) insights.push(window.mySimulation.t(`insight_approved`));
            else if (ds.insolvent) insights.push(window.mySimulation.t(`insight_insolvent`));
            else insights.push(window.mySimulation.t(`insight_blocked`));

            if (coherence < 55) insights.push(window.mySimulation.t(`insight_incoherent`));
            if (confidence < this.APPROVE_THRESHOLD && !ds.insolvent) insights.push(window.mySimulation.t(`insight_lowconfidence`));
            if (!ds.insolvent && runway < 400000) insights.push(window.mySimulation.t(`insight_thinreserves`));
            if (strong && runway >= 600000) insights.push(window.mySimulation.t(`insight_funded`));

            return {
                coherence: coherence,
                confidence: confidence,
                runway: runway,
                approved: approved,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                insolvent: ds.insolvent,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var self = this;
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var money = function(v) { try { return self._money(v); } catch (e) { return String(Math.round(v || 0)); } };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var ok = !!s.approved;
            var badge = ok
                ? '<span class="bizmodelsim-cm-badge bizmodelsim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="bizmodelsim-cm-badge bizmodelsim-cm-no">' + T('cm_missed') + '</span>';
            var insBadge = s.insolvent
                ? '<span class="bizmodelsim-cm-badge bizmodelsim-cm-warn">' + T('cm_insolvent_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="bizmodelsim-cm-metric"><span class="bizmodelsim-cm-mv">' + Math.round(s.coherence || 0) + '</span><span class="bizmodelsim-cm-ml">' + T('cm_m_coherence') + '</span></div>'
                + '<div class="bizmodelsim-cm-metric"><span class="bizmodelsim-cm-mv">' + Math.round(s.confidence || 0) + '</span><span class="bizmodelsim-cm-ml">' + T('cm_m_confidence') + '</span></div>'
                + '<div class="bizmodelsim-cm-metric"><span class="bizmodelsim-cm-mv">' + money(s.runway) + '</span><span class="bizmodelsim-cm-ml">' + T('cm_m_runway') + '</span></div>';
            return ''
                + '<div class="bizmodelsim-completion">'
                +   '<div class="bizmodelsim-cm-head">'
                +     '<div class="bizmodelsim-cm-score">' + score + '<span class="bizmodelsim-cm-score-max">/100</span></div>'
                +     '<div class="bizmodelsim-cm-grade">' + grade + ' ' + badge + insBadge + '</div>'
                +   '</div>'
                +   '<div class="bizmodelsim-cm-metrics">' + metrics + '</div>'
                +   '<div class="bizmodelsim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="bizmodelsim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.insolvent) return window.mySimulation.t(`hint_insolvent`);
            if (ds.runway < 350000 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_cash`);
            if (ds.coherence < 40) return window.mySimulation.t(`hint_coherence`);
            if (state.currentPeriod >= 3 && ds.confidence < 45) return window.mySimulation.t(`hint_confidence`);
            if (ds.coherence >= 70 && ds.confidence >= this.APPROVE_THRESHOLD) return window.mySimulation.t(`hint_strong`);
            return null;
        }

